    /**
     * Method to retrieve the Organization via OrganizationFetchOneSummary
     * @param 	summary OrganizationFetchOneSummary 
     * @return 	OrganizationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Organization getOrganization( OrganizationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "OrganizationFetchOneSummary arg cannot be null" );
    	
    	Organization entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Organization
        	// --------------------------------------
        	CompletableFuture<Organization> futureEntity = queryGateway.query(new FindOrganizationQuery( new LoadOrganizationFilter( summary.getOrganizationId() ) ), ResponseTypes.instanceOf(Organization.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Organization with id " + summary.getOrganizationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


